changeSet.sql:

if exists (select * from [INFORMATION_SCHEMA].[ROUTINES] where SPECIFIC_SCHEMA = 'integration' and SPECIFIC_NAME = 'CompleteExecution')
begin
	drop procedure [integration].[CompleteExecution];
end

changeSet.rollback:
create or alter procedure [integration].[CompleteExecution] @ExecutionID bigint, @SynchedAssetTypeID int, @AssetTypeID int, @ResourceID int as begin set nocount on;
declare @date datetime = getutcdate(), @IsFullRefresh bit = 0, @IGCAssetRelationshipBreakdown nvarchar(2500), @IGCAssetResponsibilityBreakdown nvarchar(2500), @GovernAssetResponsibilityBreakdown nvarchar(2500), @GovernAssetRelationshipCount int = 0, @GovernAssetResponsibilityCount int = 0, @MisalignedResponsibilities int = 0, @RetrievedAssetRelationshipCount int = 0, @RetrievedAssetResponsibilityCount int = 0, @GovernAssetCount int = 0, @AssetsWithMissingDefinition int = 0, @AssetsWithMissingRelationships int = 0, @AssetsWithMissingResponsibilities int = 0, @AssetsWithErrors int = 0, @RetrievedAssetCount int = 0, @GovernAddedAssetCount int = 0, @GovernAddedRelationshipCount int = 0, @GovernAddedResponsibilityCount int = 0, @GovernUpdatedAssetCount int = 0, @GovernUpdatedRelationshipCount int = 0, @GovernUpdatedResponsibilityCount int = 0, @DeleteAssetTypeID int = null, @SourceSystemCount int = 0, @PulledCount int = 0, @GovernDeletedAssetCount int = 0, @GovernDeletedAssetRelationshipCount int = 0, @hasLevel bit = 0, @hasCriteria bit = 0;
select @IsFullRefresh = IsFullRefresh, @SourceSystemCount = CurrentSourceAssetCount from integration.ExecutionAssetType where ExecutionID = @ExecutionID and SynchedAssetTypeID = @SynchedAssetTypeID;
-- Used when figuring out deletions to consider select @hasLevel = IIF([Level] is null, 0, 1) from integration.SynchedAssetType where ID = @SynchedAssetTypeID;
-- Used when figuring out deletions to consider select @hasCriteria = IIF(count(1) > 0, 1, 0) from integration.SynchedAssetTypeFieldItem where SynchedAssetTypeID = @SynchedAssetTypeID and Active = 1 and ConsiderWhenDeleting = 1;
-- Proceed with deletion ONLY if this is a full refresh. if @IsFullRefresh = 1 begin
-- Get the number of pulled assets that we have marked as having SOMe action on it. Otherwise, it is not present in any IGC page. select @PulledCount = count(1) from [integration].[AssetHash] where SynchedAssetTypeID = @SynchedAssetTypeID and Section = 1 and [Action] is not null and [UpdateHash] is not null;
if @SourceSystemCount = @PulledCount and @SourceSystemCount > 0 begin
-- Owner deletions begin drop table if exists #StagingOwners; create table #StagingOwners (AssetID bigint, SourceID nvarchar(250), ResponsibilityTypeID int, ResourceIdentifier nvarchar(250), ResolutionFieldTypeID int, ResourceID int, Error varchar(max), OverrideItemID bigint); CREATE NONCLUSTERED INDEX IX_TempStagingOwners_ResourceIdentifier ON #StagingOwners (ResourceIdentifier) INCLUDE (AssetID, ResponsibilityTypeID); CREATE NONCLUSTERED INDEX IX_TempStagingOwners_ResourceID ON #StagingOwners (ResourceID) INCLUDE (AssetID, ResponsibilityTypeID); CREATE NONCLUSTERED INDEX IX_TempStagingOwners_ResourceIDAction ON #StagingOwners (ResourceID) INCLUDE (AssetID, ResponsibilityTypeID); CREATE NONCLUSTERED INDEX IX_TempStagingOwners_DeleteAndUpdateStepIndex ON #StagingOwners (ResponsibilityTypeID, AssetID);
-- Resolution Type = 1 insert into #StagingOwners (AssetID, SourceID, ResponsibilityTypeID, ResourceIdentifier, ResolutionFieldTypeID) select A.ID as AssetID ,substring(ltrim(rtrim(J.SourceID)), 1, 250) ,R.ResponsibilityTypeID ,substring(rtrim(ltrim(J.FieldValue)), 1, 250) ,R.ResolutionFieldTypeID from [integration].[AssetHash] H inner join integration.AssetField J on J.SynchedAssetTypeID = H.SynchedAssetTypeID and J.Section = H.Section and J.SourceID = H.SourceID inner join Asset A on A.AssetTypeID = @AssetTypeID and A.SourceID = J.SourceID inner join [integration].[SynchedAssetTypeRoleItem] R on R.SynchedAssetTypeID = J.SynchedAssetTypeID and R.SourceIdField = J.FieldName and R.ResolutionType = 1 where H.SynchedAssetTypeID = @SynchedAssetTypeID and H.Section = 3 and substring(rtrim(ltrim(J.FieldValue)), 1, 250) <> '';
-- Resolution Type = 2 insert into #StagingOwners (AssetID, SourceID, ResponsibilityTypeID, ResourceIdentifier, ResolutionFieldTypeID) select A.ID as AssetID ,substring(ltrim(rtrim(J.SourceID)), 1, 250) ,R.ResponsibilityTypeID ,S._id ,R.ResolutionFieldTypeID from [integration].[AssetHash] H inner join integration.AssetField J on J.SynchedAssetTypeID = H.SynchedAssetTypeID and J.Section = H.Section and J.SourceID = H.SourceID inner join Asset A on A.AssetTypeID = @AssetTypeID and A.SourceID = J.SourceID inner join [integration].[SynchedAssetTypeRoleItem] R on R.SynchedAssetTypeID = J.SynchedAssetTypeID and R.SourceIdField = J.FieldName and R.ResolutionType = 2 cross apply OPENJSON(J.FieldValue) SR cross apply OPENJSON(SR.[value]) with (_id nvarchar(max) '$._id') S where ISJSON(J.FieldValue) = 1 and H.SynchedAssetTypeID = @SynchedAssetTypeID and H.Section = 3 and SR.[key] = 'items' and SR.[value] <> '[]';
-- Resolve the resource ID based on the incoming identifiers from staging data. update T set T.ResourceID = RE.ResourceID from #StagingOwners T inner join Field F on F.ObjectType = 'Resource' and F.Value = T.ResourceIdentifier and F.FieldTypeID = T.ResolutionFieldTypeID inner join reporting.Global_Resource RE on RE.ResourceID = F.ObjectID;
select @RetrievedAssetResponsibilityCount = count(1) from #StagingOwners;
--Log error here for items that do not have identified owners. insert into integration.ExecutionAssetTypeError (ExecutionID, SynchedAssetTypeID, SourceID, ErrorMessages, ErrorCode) select @ExecutionID, @SynchedAssetTypeID, H.SourceID, ( select ResponsibilityTypeID, ResourceIdentifier from #StagingOwners where SourceID = H.SourceID and ResourceIdentifier is not null and ResourceIdentifier <> '' and ResourceID is null for json path ) as ErrorMessages, 7 as ErrorCode from #StagingOwners H where AssetID is not null and ResourceIdentifier is not null and ResourceID is null group by SourceID;
-- Log these owner deletions. insert into integration.ExecutionAssetTypeLog (ExecutionID, SynchedAssetTypeID, Section, [Action], [Log]) select @ExecutionID, @SynchedAssetTypeID, 3, 'D', '{' + '"SourceID": "' + A.SourceID + '", ' + '"ResourceId": "' + cast(T.SecurityAssetID as nvarchar) + '", ' + '"ResponsibilityTypeID": "' + cast(T.ResponsibilityTypeID as nvarchar) + '"' + '}' as [Log] from ResponsibilityTypeRelationOverrideItem T inner join Asset A on A.ID = T.AssetID and A.AssetTypeID = @AssetTypeID left join #StagingOwners S on S.AssetID = T.AssetID and S.ResponsibilityTypeID = T.ResponsibilityTypeID where S.SourceID is null;
---- Delete the now invalid owner records. if @hasCriteria = 1 and @hasLevel = 1 begin delete T --select * from ResponsibilityTypeRelationOverrideItem T inner join Asset A on A.ID = T.AssetID and A.AssetTypeID = @AssetTypeID inner join integration.SynchedAssetType S on S.AssetTypeID = A.AssetTypeID and S.ID = @SynchedAssetTypeID cross apply dbo.GetAssetLevelById(A.ID) L cross apply ( select F.AssetID from integration.SynchedAssetTypeFieldItem SF inner join FieldType T on T.Name = SF.TargetField and SF.ConsiderWhenDeleting = 1 and SF.SynchedAssetTypeID = S.ID and SF.Active = 1 and T.AssetTypeID = S.AssetTypeID inner join Field F on F.FieldTypeID = T.ID and F.Value = SF.DefaultValue and F.AssetID = A.ID group by F.AssetID ) D left join #StagingOwners O on O.AssetID = T.AssetID and O.ResponsibilityTypeID = T.ResponsibilityTypeID where O.SourceID is null and L.[Level] = S.[Level]; end;
if @hasCriteria = 1 and @hasLevel = 0 begin delete T --select * from ResponsibilityTypeRelationOverrideItem T inner join Asset A on A.ID = T.AssetID and A.AssetTypeID = @AssetTypeID inner join integration.SynchedAssetType S on S.AssetTypeID = A.AssetTypeID and S.ID = @SynchedAssetTypeID cross apply ( select F.AssetID from integration.SynchedAssetTypeFieldItem SF inner join FieldType T on T.Name = SF.TargetField and SF.ConsiderWhenDeleting = 1 and SF.SynchedAssetTypeID = S.ID and SF.Active = 1 and T.AssetTypeID = S.AssetTypeID inner join Field F on F.FieldTypeID = T.ID and F.Value = SF.DefaultValue and F.AssetID = A.ID group by F.AssetID ) D left join #StagingOwners O on O.AssetID = T.AssetID and O.ResponsibilityTypeID = T.ResponsibilityTypeID where O.SourceID is null; end;
if @hasLevel = 1 and @hasCriteria = 0 begin delete T --select * from ResponsibilityTypeRelationOverrideItem T inner join Asset A on A.ID = T.AssetID and A.AssetTypeID = @AssetTypeID inner join integration.SynchedAssetType S on S.AssetTypeID = A.AssetTypeID and S.ID = @SynchedAssetTypeID cross apply dbo.GetAssetLevelById(A.ID) L left join #StagingOwners O on O.AssetID = T.AssetID and O.ResponsibilityTypeID = T.ResponsibilityTypeID where O.SourceID is null and L.[Level] = S.[Level]; end;
if @hasLevel = 0 and @hasCriteria = 0 begin delete T --select * from ResponsibilityTypeRelationOverrideItem T inner join Asset A on A.ID = T.AssetID and A.AssetTypeID = @AssetTypeID left join #StagingOwners O on O.AssetID = T.AssetID and O.ResponsibilityTypeID = T.ResponsibilityTypeID where O.SourceID is null; end end;
-- Asset deletions begin select @DeleteAssetTypeID = AssetTypeID from integration.SynchedAssetType where ID = @SynchedAssetTypeID
drop table if exists #DeleteAssets;
create table #DeleteAssets (ID int identity, AssetID bigint, Object varchar(50), ObjectID int, SourceID varchar(100), FactorTowardsDeletedCount bit); CREATE CLUSTERED INDEX CIX_TempDeleteAssets ON #DeleteAssets (ID); CREATE NONCLUSTERED INDEX IX_TempDeleteAssets_SourceID ON #DeleteAssets (SourceID);
insert into #DeleteAssets select A.ID, A.Object, A.ObjectID, A.SourceID, 1 as FactorTowardsDeletedCount from integration.AssetHash H inner join Asset A on A.AssetTypeID = @AssetTypeID and H.SynchedAssetTypeID = @SynchedAssetTypeID and H.Section = 1 and A.SourceID = H.SourceID and ( (H.[UpdateHash] is null) or (H.[Hash] is null and H.[Action] != 'A') or (H.[Hash] is not null and H.[Action] is null) );
insert into #DeleteAssets select ID, Object, ObjectID, SourceID, 0 as FactorTowardsDeletedCount from Asset where AssetTypeID = @AssetTypeID and SourceID not in ( select H.SourceID from integration.AssetHash H inner join integration.SynchedAssetType S on S.ID = H.SynchedAssetTypeID and S.AssetTypeID = @AssetTypeID and H.Section = 1 );
-- Now loop through and perform an appropriate delete using normal stored procedure. declare @current int = 1, @max int, @o varchar(50), @oID int, @oAssetId bigint;
select @max = coalesce(max(ID),0) from #DeleteAssets
while @current <= @max begin select @o = Object, @oID = ObjectID, @oAssetId = AssetID from #DeleteAssets where ID = @current
exec DeleteObject @o, @oID, 0 delete Asset where ID = @oAssetId
set @current = @current + 1 end;
-- Delete from staging tables. delete H from integration.AssetHash H left join Asset A on A.AssetTypeID = @AssetTypeID and A.SourceID = H.SourceID where H.SynchedAssetTypeID = @SynchedAssetTypeID and H.[UpdateHash] is null and A.ID is null;
delete T from integration.AssetHash T inner join #DeleteAssets S on T.SynchedAssetTypeID = @SynchedAssetTypeID and S.SourceID = T.SourceID;
delete T from integration.AssetField T inner join #DeleteAssets S on T.SynchedAssetTypeID = @SynchedAssetTypeID and S.SourceID = T.SourceID;
-- Calculate the metric to eventually store. select @GovernDeletedAssetCount = count(1) from #DeleteAssets where FactorTowardsDeletedCount = 1
insert into integration.ExecutionAssetTypeLog (ExecutionID, SynchedAssetTypeID, Section, [Action], [Log]) select @ExecutionID, @SynchedAssetTypeID, 1, 'D', '{' + '"SourceID": "' + SourceID + '", ' + '"AssetID": "' + cast(AssetID as nvarchar) + '"' + '}' as [Log] from #DeleteAssets; end;
-- Perform a full compare of relationships. begin merge [integration].[AssetFieldRelationship] as T using ( select D.SynchedAssetTypeID, D.SourceID, D.FieldName, DRA.AssetSourceType, DRA.AssetSourceID, R.[IsSubject], RT.IntersectTypeID from [integration].[AssetHash] H inner join integration.AssetField D on D.SynchedAssetTypeID = H.SynchedAssetTypeID and H.SynchedAssetTypeID = @SynchedAssetTypeID and D.Section = H.Section and D.SourceID = H.SourceID and D.Section = 2 inner join integration.SynchedAssetType S on S.ID = D.SynchedAssetTypeID inner join integration.SynchedAssetTypeRelationItem R on R.SynchedAssetTypeID = S.ID and R.SourceField = D.FieldName cross apply openjson(D.FieldValue) DR cross apply openjson(DR.value) with (AssetSourceType nvarchar(500) '$._type', name nvarchar(500) '$._name', AssetSourceID nvarchar(500) '$._id') DRA inner join [integration].[SynchedAssetTypeRelationItemTarget] RT on RT.SynchedAssetTypeRelationItemID = R.ID and RT.[SourceAssetType] = DRA.AssetSourceType where DRA.AssetSourceID not like 'extern%' ) as S on (T.SynchedAssetTypeID = S.SynchedAssetTypeID and T.SourceID = S.SourceID and T.FieldName = S.FieldName and T.AssetSourceType = S.AssetSourceType and T.AssetSourceID = S.AssetSourceID) when matched then update set T.IsSubject = S.IsSubject, T.IntersectTypeID = S.IntersectTypeID, T.Present = 1 when not matched by target then insert (SynchedAssetTypeID, SourceID, FieldName, AssetSourceType, AssetSourceID, IsSubject, IntersectTypeID, Present) values (S.SynchedAssetTypeID, S.SourceID, S.FieldName, S.AssetSourceType, S.AssetSourceID, S.IsSubject, S.IntersectTypeID, 1);
-- Resolve subjects and objects. update R set R.SubjectID = S.ID, R.ObjectID = O.ID from [integration].[AssetFieldRelationship] R inner join Asset S on S.SourceID = R.SourceID inner join Asset O on O.SourceID = R.AssetSourceID where R.SynchedAssetTypeID = @SynchedAssetTypeID and R.IsSubject = 1;
update R set R.SubjectID = S.ID, R.ObjectID = O.ID from [integration].[AssetFieldRelationship] R inner join Asset S on S.SourceID = R.AssetSourceID inner join Asset O on O.SourceID = R.SourceID where R.SynchedAssetTypeID = @SynchedAssetTypeID and R.IsSubject = 0;
-- See if the Intersect record already exists. update R set R.IntersectID = I.ID from [integration].[AssetFieldRelationship] R inner join Asset S on S.ID = R.SubjectID inner join Asset O on O.ID = R.ObjectID inner join [Intersect] I on I.IntersectTypeID = R.IntersectTypeID and I.Subject = S.Object and I.SubjectID = S.ObjectID and I.Object = O.Object and I.ObjectID = O.ObjectID where R.SynchedAssetTypeID = @SynchedAssetTypeID;
-- Add any intersect records that do not yet exist. insert into [Intersect] (IntersectTypeID, Subject, SubjectID, Object, ObjectID, CreatedBy, UpdatedBy, [Owner]) select R.IntersectTypeID, S.Object as Subject, S.ObjectID as SubjectID, O.Object, O.ObjectID, @ResourceID, @ResourceID, 'IGC' as [Owner] from integration.AssetFieldRelationship R inner join Asset S on S.ID = R.SubjectID inner join Asset O on O.ID = R.ObjectID where R.SynchedAssetTypeID = @SynchedAssetTypeID and R.Present = 1 and R.IntersectID is null;
-- Now update the intersect record ID for those that we may have just added above. update R set R.IntersectID = I.ID from [integration].[AssetFieldRelationship] R inner join Asset S on S.ID = R.SubjectID inner join Asset O on O.ID = R.ObjectID inner join [Intersect] I on I.IntersectTypeID = R.IntersectTypeID and I.Subject = S.Object and I.SubjectID = S.ObjectID and I.Object = O.Object and I.ObjectID = O.ObjectID where R.SynchedAssetTypeID = @SynchedAssetTypeID and R.IntersectID is null;
drop table if exists #RemovedRelationships; create table #RemovedRelationships ( Uid uniqueidentifier, IntersectTypeID int, IntersectID int, SubjectSourceID nvarchar(250), ObjectSourceID nvarchar(250) ); CREATE CLUSTERED INDEX IX_TempRemovedRelationships ON #RemovedRelationships (IntersectID);
-- Get a list of intersect records that should no longer exist. insert into #RemovedRelationships select D.Uid, D.IntersectTypeID, D.IntersectID, case when D.IsSubject = 1 then D.SourceID else D.AssetSourceID end, case when D.IsSubject = 0 then D.AssetSourceID else D.SourceID end from [integration].[AssetFieldRelationship] D where D.SynchedAssetTypeID = @SynchedAssetTypeID and D.Present = 0 and D.IntersectID is not null and D.IntersectID not in (select IntersectID from [integration].[AssetFieldRelationship] where SynchedAssetTypeID <> @SynchedAssetTypeID and Present = 1);
-- Remove the intersect record. delete T from [Intersect] T inner join #RemovedRelationships S on T.ID = S.IntersectID;
delete [integration].[AssetFieldRelationship] where SynchedAssetTypeID = @SynchedAssetTypeID and Present = 0;
-- Do final removal of defunct relationships that are not even listed in assetrelationship integration table. delete [Intersect] where IntersectTypeID in (select distinct RIT.IntersectTypeID from integration.SynchedAssetTypeRelationItem RI inner join integration.SynchedAssetTypeRelationItemTarget RIT on RIT.SynchedAssetTypeRelationItemID = RI.ID and RI.SynchedAssetTypeID = @SynchedAssetTypeID) and ID not in ( select IntersectID from [integration].[AssetFieldRelationship] where SynchedAssetTypeID = @SynchedAssetTypeID ) and ID not in ( select I.ID from [Intersect] I inner join [integration].[AssetFieldRelationship] AR on AR.SynchedAssetTypeID <> @SynchedAssetTypeID and AR.IntersectID = I.ID );
-- Reset the staging table relationships to be listed as NOT present, to prepare for the next full refresh execution. update [integration].[AssetFieldRelationship] set [Present] = 0 where SynchedAssetTypeID = @SynchedAssetTypeID;
-- Calculate relationship metrics. select @GovernDeletedAssetRelationshipCount = count(1) from #RemovedRelationships;
select @GovernAssetRelationshipCount = count(1) from [integration].[AssetFieldRelationship] where SynchedAssetTypeID = @SynchedAssetTypeID and IntersectID is not null;
select @RetrievedAssetRelationshipCount = count(1) from [integration].[AssetFieldRelationship] where SynchedAssetTypeID = @SynchedAssetTypeID;
-- Log relationship these deletions. insert into integration.ExecutionAssetTypeLog (ExecutionID, SynchedAssetTypeID, Section, [Action], [Log]) select @ExecutionID, @SynchedAssetTypeID, 2, 'D', '{' + '"SubjectSourceID": "' + SubjectSourceID + '", ' + '"ObjectSourceID": "' + ObjectSourceID + '", ' + '"IntersectID": "' + cast(IntersectID as nvarchar) + '"' + '}' as [Log] from #RemovedRelationships; end;
end else begin -- ERROR CODE: 4 update integration.ExecutionAssetType set ErrorMessage = coalesce(ErrorMessage + '; ', '') + 'The reported asset count from the source system did not match what we were able to pull from the API. Will not proceed with deletion.' where ExecutionID = @ExecutionID and SynchedAssetTypeID = @SynchedAssetTypeID; end
end
if @SourceSystemCount > 0 begin select @GovernAddedAssetCount = count(1) from integration.AssetHash H inner join Asset A on A.AssetTypeID = @AssetTypeID and H.SynchedAssetTypeID = @SynchedAssetTypeID and H.Section = 1 and A.SourceID = H.SourceID and H.[Action] = 'A';
select @GovernAddedRelationshipCount = count(1) from integration.ExecutionAssetTypeLog where ExecutionID = @ExecutionID and SynchedAssetTypeID = @SynchedAssetTypeID and Section = 2 and [Action] = 'A';
select GovernAddedResponsibilityCount = count(1) from integration.ExecutionAssetTypeLog where ExecutionID = @ExecutionID and SynchedAssetTypeID = @SynchedAssetTypeID and Section = 3 and [Action] = 'A';
select @GovernUpdatedAssetCount = count(1) from integration.AssetHash H inner join Asset A on A.AssetTypeID = @AssetTypeID and H.SynchedAssetTypeID = @SynchedAssetTypeID and H.Section = 2 and A.SourceID = H.SourceID and H.[Action] = 'U';
select @GovernUpdatedRelationshipCount = count(1) from integration.ExecutionAssetTypeLog where ExecutionID = @ExecutionID and SynchedAssetTypeID = @SynchedAssetTypeID and Section = 2 and [Action] = 'U';
select @GovernUpdatedResponsibilityCount = count(1) from integration.ExecutionAssetTypeLog where ExecutionID = @ExecutionID and SynchedAssetTypeID = @SynchedAssetTypeID and Section = 3 and [Action] = 'U';
select @AssetsWithMissingDefinition = coalesce(sum(case when RequestNumber is not null then 1 else 0 end), 0) from integration.AssetHash where SynchedAssetTypeID = @SynchedAssetTypeID and Section = 1 and [Action] is null select @AssetsWithMissingRelationships = coalesce(sum(case when RequestNumber is not null then 1 else 0 end), 0) from integration.AssetHash where SynchedAssetTypeID = @SynchedAssetTypeID and Section = 2 and [Action] is null select @AssetsWithMissingResponsibilities = coalesce(sum(case when RequestNumber is not null then 1 else 0 end), 0) from integration.AssetHash where SynchedAssetTypeID = @SynchedAssetTypeID and Section = 3 and [Action] is null select @AssetsWithErrors = coalesce(sum(1), 0) from ( select SourceID from [integration].[ExecutionAssetTypeError] where ExecutionID = @ExecutionID and SynchedAssetTypeID = @SynchedAssetTypeID group by SourceID) O;
select @GovernAssetRelationshipCount = count(1) from [integration].[AssetFieldRelationship] where SynchedAssetTypeID = @SynchedAssetTypeID and IntersectID is not null;
if (@GovernAssetRelationshipCount is null) or (@GovernAssetRelationshipCount < 0) begin set @GovernAssetRelationshipCount = 0 end
set @GovernAssetResponsibilityBreakdown = ( select I_RT.Name as 'role', count(1) as 'count' from integration.AssetHash I_EA inner join Asset I_A on I_A.AssetTypeID = @AssetTypeID and I_A.SourceID = I_EA.SourceID inner join ResponsibilityTypeRelationOverrideItem I_R on I_R.AssetID = I_A.ID inner join ResponsibilityType I_RT on I_RT.ID = I_R.ResponsibilityTypeID inner join integration.SynchedAssetTypeRoleItem I_RI on I_RI.SynchedAssetTypeID = @SynchedAssetTypeID and I_RI.ResponsibilityTypeID = I_RT.ID and I_RI.[Active] = 1 where I_EA.SynchedAssetTypeID = @SynchedAssetTypeID and I_EA.Section = 3 group by I_RT.Name for json path );
select @GovernAssetResponsibilityCount = count(1) from integration.AssetHash I_EA inner join Asset I_A on I_A.AssetTypeID = @AssetTypeID and I_A.SourceID = I_EA.SourceID inner join ResponsibilityTypeRelationOverrideItem I_R on I_R.AssetID = I_A.ID inner join ResponsibilityType I_RT on I_RT.ID = I_R.ResponsibilityTypeID inner join integration.SynchedAssetTypeRoleItem I_RI on I_RI.SynchedAssetTypeID = @SynchedAssetTypeID and I_RI.ResponsibilityTypeID = I_RT.ID and I_RI.[Active] = 1 where I_EA.SynchedAssetTypeID = @SynchedAssetTypeID and I_EA.Section = 3;
if (@GovernAssetResponsibilityCount is null) or (@GovernAssetResponsibilityCount < 0) begin set @GovernAssetResponsibilityCount = 0 end
select @MisalignedResponsibilities = count(1) from integration.SynchedAssetTypeRoleItem RO inner join ResponsibilityTypeRelationOverrideItem O on O.ResponsibilityTypeID = RO.ResponsibilityTypeID and RO.SynchedAssetTypeID = @SynchedAssetTypeID and RO.[Active] = 1 and O.SecurityAsset = 'R' and O.AssetID > 0 inner join Asset A on A.ID = O.AssetID inner join integration.SynchedAssetType SAT on SAT.ID = RO.SynchedAssetTypeID and SAT.AssetTypeID = A.AssetTypeID inner join integration.AssetHash EA on EA.SynchedAssetTypeID = @SynchedAssetTypeID and EA.Section = 2 and A.SourceID = EA.SourceID inner join integration.AssetField C on C.SourceID = EA.SourceID and C.Section = 2 inner join FieldType RFT on RFT.Object = 'ResourceType' and RFT.ID = RO.ResolutionFieldTypeID inner join Field RF on RF.FieldTypeID = RFT.ID and RF.ObjectType = 'Resource' and RF.ObjectID = O.SecurityAssetID where C.FieldName = RO.SourceIdField and RF.Value <> C.FieldValue;
select @RetrievedAssetCount = coalesce(sum(1), 0) from [integration].[AssetHash] where SynchedAssetTypeID = @SynchedAssetTypeID and Section = 1 and RequestNumber is not null;
select @RetrievedAssetRelationshipCount = count(1) from integration.AssetFieldRelationship where SynchedAssetTypeID = @SynchedAssetTypeID;
begin -- Calculate Govern Asset Count declare @hierarchyContributingAssetTypeCount int;
select @hierarchyContributingAssetTypeCount = count(1) from integration.SynchedAssetType where AssetTypeID = @AssetTypeID;
declare @CountLevel int, @ObjectType varchar(50), @PredicateType int = 3;
select @ObjectType = Object from integration.SynchedAssetType where ID = @SynchedAssetTypeID;
if (@ObjectType = 'PolicyType' OR @ObjectType = 'TaxonomyType') begin set @PredicateType = 4 end;
with ht as ( select A.ID, I.Subject, I.SubjectID, 1 as Level from integration.SynchedAssetType S with (nolock) inner join AssetType A with (nolock) on A.ID = S.AssetTypeID inner join IntersectType I with (nolock) on I.Object = A.Object and I.ObjectID = A.ObjectID inner join [Predicate] P with (nolock) on P.ID = I.PredicateID and P.[Type] = @PredicateType where S.ID = @SynchedAssetTypeID union all select C.ID, I.Subject, I.SubjectID, C.Level+1 as Level from AssetType A with (nolock) inner join ht as C on C.Subject = A.Object and C.SubjectID = A.ObjectID inner join IntersectType I with (nolock) on I.Object = A.Object and I.ObjectID = A.ObjectID inner join [Predicate] P with (nolock) on P.ID = I.PredicateID and P.[Type] = @PredicateType where C.Level <= 25 )
select @CountLevel = max([Level]) from ht;
if @hierarchyContributingAssetTypeCount = 1 begin set @hasLevel = 0 set @CountLevel = null end;
if @hasCriteria = 1 and @hasLevel = 1 begin select @GovernAssetCount = count(1) from Asset A inner join integration.SynchedAssetType S on S.AssetTypeID = A.AssetTypeID and S.ID = @SynchedAssetTypeID cross apply dbo.GetAssetLevelById(A.ID) L cross apply ( select F.AssetID from integration.SynchedAssetTypeFieldItem SF inner join FieldType T on T.Name = SF.TargetField and SF.ConsiderWhenDeleting = 1 and SF.SynchedAssetTypeID = S.ID and SF.Active = 1 and T.AssetTypeID = S.AssetTypeID inner join Field F on F.FieldTypeID = T.ID and F.Value = SF.DefaultValue and F.AssetID = A.ID group by F.AssetID ) D where A.AssetTypeID = @AssetTypeID and L.[Level] = S.[Level] end;
if @hasCriteria = 1 and @hasLevel = 0 begin with h2 as ( select A.ID, A.AssetTypeID, I.Subject, I.SubjectID, 1 as Level from integration.SynchedAssetType S with (nolock) inner join Asset A with (nolock) on A.AssetTypeID = S.AssetTypeID inner join PredicateIntersect I with (nolock) on I.PredicateType = @PredicateType and I.Object = A.Object and I.ObjectID = A.ObjectID where S.ID = @SynchedAssetTypeID union all select C.ID, C.AssetTypeID, I.Subject, I.SubjectID, C.Level+1 as Level from Asset A with (nolock) inner join h2 as C on C.Subject = A.Object and C.SubjectID = A.ObjectID inner join PredicateIntersect I with (nolock) on I.PredicateType = @PredicateType and I.Object = A.Object and I.ObjectID = A.ObjectID ) select @GovernAssetCount = count(1) from h2 A cross apply ( select F.AssetID from integration.SynchedAssetTypeFieldItem SF inner join FieldType T on T.Name = SF.TargetField and SF.ConsiderWhenDeleting = 1 and SF.SynchedAssetTypeID = @SynchedAssetTypeID and SF.Active = 1 and T.AssetTypeID = A.AssetTypeID inner join Field F on F.FieldTypeID = T.ID and F.Value = SF.DefaultValue and F.AssetID = A.ID group by F.AssetID ) D where A.[Level] = @CountLevel end;
if @hasLevel = 1 and @hasCriteria = 0 begin select @GovernAssetCount = count(1) from Asset A inner join integration.SynchedAssetType S on S.AssetTypeID = A.AssetTypeID and S.ID = @SynchedAssetTypeID cross apply dbo.GetAssetLevelById(A.ID) L where A.AssetTypeID = @AssetTypeID and L.[Level] = S.[Level] end;
if @hasLevel = 0 and @hasCriteria = 0 begin if @CountLevel is null begin select @GovernAssetCount = count(1) from Asset A inner join integration.SynchedAssetType S on S.AssetTypeID = A.AssetTypeID and S.ID = @SynchedAssetTypeID where A.AssetTypeID = @AssetTypeID end else begin with h4 as ( select A.ID, A.AssetTypeID, I.Subject, I.SubjectID, 1 as Level from integration.SynchedAssetType S with (nolock) inner join Asset A with (nolock) on A.AssetTypeID = S.AssetTypeID inner join PredicateIntersect I with (nolock) on I.PredicateType = @PredicateType and I.Object = A.Object and I.ObjectID = A.ObjectID where S.ID = @SynchedAssetTypeID union all select C.ID, C.AssetTypeID, I.Subject, I.SubjectID, C.Level+1 as Level from Asset A with (nolock) inner join h4 as C on C.Subject = A.Object and C.SubjectID = A.ObjectID inner join PredicateIntersect I with (nolock) on I.PredicateType = @PredicateType and I.Object = A.Object and I.ObjectID = A.ObjectID ) select @GovernAssetCount = count(1) from h4 where [Level] = @CountLevel end end end
update integration.ExecutionAssetType set AssetsWithMissingDefinition = @AssetsWithMissingDefinition, AssetsWithMissingRelationships = @AssetsWithMissingRelationships, AssetsWithMissingResponsibilities = @AssetsWithMissingResponsibilities, AssetsWithErrors = @AssetsWithErrors,
RetrievedAssetCount = @RetrievedAssetCount, RetrievedAssetRelationshipCount = @RetrievedAssetRelationshipCount, RetrievedAssetResponsibilityCount = @RetrievedAssetResponsibilityCount,
GovernAssetCount = @GovernAssetCount, GovernAssetRelationshipCount = @GovernAssetRelationshipCount, GovernAssetResponsibilityCount = @GovernAssetResponsibilityCount, GovernAssetResponsibilityBreakdown = @GovernAssetResponsibilityBreakdown,
MisalignedResponsibilities = @MisalignedResponsibilities,
GovernAddedAssetCount = @GovernAddedAssetCount, GovernAddedRelationshipCount = @GovernAddedRelationshipCount, GovernAddedResponsibilityCount = @GovernAddedResponsibilityCount,
GovernUpdatedAssetCount = @GovernUpdatedAssetCount, GovernUpdatedRelationshipCount = @GovernUpdatedRelationshipCount, GovernUpdatedResponsibilityCount = @GovernUpdatedResponsibilityCount,
GovernDeletedAssetCount = @GovernDeletedAssetCount, GovernDeletedRelationshipCount = @GovernDeletedAssetRelationshipCount where ExecutionID = @ExecutionID and SynchedAssetTypeID = @SynchedAssetTypeID; end
--Clear out hashes for assets that have an error on them, so we try again on next refresh. update T set T.[Hash] = 'error' from integration.AssetHash T inner join ( select SynchedAssetTypeID, SourceID from integration.ExecutionAssetTypeError where ExecutionID = @ExecutionID and SynchedAssetTypeID = @SynchedAssetTypeID group by SynchedAssetTypeID, SourceID ) S on S.SynchedAssetTypeID = T.SynchedAssetTypeID and S.SourceID = T.SourceID;
-- Clear working tables for this execution. delete integration.ExecutionAssetField where SynchedAssetTypeID = @SynchedAssetTypeID;
update integration.AssetHash set RequestNumber = null, [Action] = null, UpdateHash = null where SynchedAssetTypeID = @SynchedAssetTypeID; end
